SELECT 
FROM profit_records pr
LEFT JOIN agents a ON pr.agent_id = a.id
LEFT JOIN products p ON pr.product_id = p.id
LEFT JOIN merchants m ON pr.merchant_id = m.id
LEFT JOIN machines mac ON pr.machine_id = mac.id
WHERE 1=1

    AND pr.agent_id = #{agentId}


    AND pr.product_id = #{productId}


    AND pr.status = #{status}


    AND pr.create_time >= #{startTime}


    AND pr.create_time <= #{endTime}

ORDER BY pr.create_time DESC

SELECT COALESCE(SUM(profit_amount), 0)
FROM profit_records
WHERE agent_id = #{agentId}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}
